(() => {
  'use strict';
  const atlasDataUrl = 'data:image/png;base64,';
  const names = ["grass_top", "grass_side", "dirt", "stone", "sand", "log_side", "log_top", "leaves", "brick", "glowstone", "planks", "cobble", "glass", "wool_white", "wool_red", "wool_blue", "wool_green", "wool_yellow", "coal_ore", "iron_ore", "gold_ore", "diamond_ore", "obsidian", "quartz", "bookshelf", "crafting_side", "crafting_top", "furnace_side", "furnace_front", "snow", "clay", "mossy_cobble", "dark_planks", "pumpkin_side", "pumpkin_top", "pumpkin_face", "cactus_side", "cactus_top", "concrete", "bedrock"];
  window.VoxelTextures = {
    atlasDataUrl,
    tileSize: 32,
    columns: 8,
    rows: 5,
    names,
    tileIndex(name) { return names.indexOf(name); },
    loadImage() {
      return new Promise((resolve, reject) => {
        const image = new Image();
        image.onload = () => resolve(image);
        image.onerror = reject;
        image.src = atlasDataUrl;
      });
    }
  };
})();
